// Curated homepage hero rotation.
//
// Every slide is a real Arees / Dahab product photograph from /public. The
// database brand images are intentionally NOT used here: the seeded brand
// records point at generic stock photography, which made the hero show
// Unsplash art instead of the actual bottles.
//
// Desktop uses the wide landscape original; mobile uses a 2:3 portrait crop
// generated by `npm run hero:mobile` (scripts/generate-hero-mobile.mjs) so the
// bottle stays framed on narrow phones instead of being cropped away.
//
// `focus` / `mobileFocus` are object-position values. `mobileFocus` is applied
// on top of the already-framed portrait crop, so it only needs to fine-tune
// the vertical composition (products above the mobile text block).

const HOME_HERO_SLIDES = [
  {
    src: '/Hero.webp',
    mobileWebp: '/Hero-mobile.webp',
    alt: 'Arees Perfumes — Aseel attar and Pink Musk roll-on collection',
    brandName: 'Arees Perfumes',
    focus: '85% 40%',
    mobileFocus: '50% 42%',
    brightness: 1,
  },
  {
    src: '/arees12ml-hero.webp',
    mobileWebp: '/arees12ml-hero-mobile.webp',
    alt: 'Arees 12ml non-alcoholic parfum bottle',
    brandName: 'Arees 12ml',
    focus: '52% 50%',
    mobileFocus: '50% 40%',
    brightness: 1,
  },
  {
    src: '/areesluxury-hero.webp',
    mobileWebp: '/areesluxury-hero-mobile.webp',
    alt: 'Arees Luxury eau de parfum bottle',
    brandName: 'Arees Luxury',
    focus: '62% 55%',
    mobileFocus: '50% 42%',
    brightness: 1,
  },
  {
    src: '/bakhoor-hero.webp',
    mobileWebp: '/bakhoor-hero-mobile.webp',
    alt: 'Arees Bakhoor Ad Dawli incense collection',
    brandName: 'Arees Bakhoor',
    focus: '50% 55%',
    mobileFocus: '50% 42%',
    brightness: 0.95,
  },
  {
    src: '/Dahab-hero.webp',
    mobileWebp: '/Dahab-hero-mobile.webp',
    alt: 'Dahab 6ml roll-on perfume collection',
    brandName: 'Dahab 6ml',
    focus: '53% 45%',
    mobileFocus: '50% 42%',
    brightness: 1,
  },
]

/**
 * Build the homepage hero slides.
 *
 * The order is fixed: the Arees signature image first (also the LCP preload in
 * index.html), followed by the four product lines. No stock photography and no
 * product packshots are mixed in.
 *
 * @returns {Array<Object>} copies of the curated slide metadata
 */
export function buildHomeHeroImages() {
  return HOME_HERO_SLIDES.map((slide) => ({ ...slide }))
}
